styles:
/* === TAVA ADS STORY REEL — infinite left-scrolling video marquee === */
.tava-ads{background:#FFFFFF;padding:34px 0 10px;overflow:hidden}
.tava-ads-label{font-family:Kanit,sans-serif;font-weight:700;letter-spacing:.28em;text-transform:uppercase;font-size:13px;color:#000000;text-align:center;margin:0 0 18px}
.tava-ads-viewport{overflow:hidden;-webkit-mask-image:linear-gradient(90deg,transparent,#000 4%,#000 96%,transparent);mask-image:linear-gradient(90deg,transparent,#000 4%,#000 96%,transparent)}
.tava-ads-track{display:flex;gap:16px;width:max-content;animation:tava-ads-scroll 68s linear infinite}
.tava-ads-viewport:hover .tava-ads-track{animation-play-state:paused}
@keyframes tava-ads-scroll{to{transform:translateX(-50%)}}
.tava-ad-card{flex:0 0 auto;width:190px;height:338px;border-radius:22px;overflow:hidden;background:#000000;border:2px solid #D8C19A;box-shadow:0 10px 28px rgba(0,0,0,.18)}
.tava-ad-card{position:relative;cursor:pointer}
.tava-ad-card video{width:100%;height:100%;object-fit:cover;display:block;pointer-events:none}
.tava-ads-desc{font-family:'Futura book font',sans-serif;font-size:19px;line-height:1.5;color:#000000;text-align:center;max-width:640px;margin:0 auto 20px;padding:0 20px}
.tava-ad-play{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);display:flex;align-items:center;justify-content:center;z-index:2;pointer-events:none;filter:drop-shadow(0 1px 5px rgba(0,0,0,.5))}
.tava-ad-modal{position:fixed;inset:0;background:rgba(0,0,0,.92);z-index:9999;display:none;align-items:center;justify-content:center;padding:20px}
.tava-ad-modal.open{display:flex}
.tava-ad-modal video{max-width:min(420px,92vw);max-height:86vh;border-radius:22px;border:2px solid #D8C19A;background:#000}
.tava-ad-modal-close{position:absolute;top:18px;right:22px;background:#000000;color:#FFFFFF;border:none;width:44px;height:44px;border-radius:50%;font-size:22px;cursor:pointer;line-height:1}
@media(max-width:600px){.tava-ad-card{width:150px;height:267px}}

.gold-tail{background-image:linear-gradient(100deg,#B78B45 0%,#D8C19A 30%,#F3E5BC 50%,#D8C19A 70%,#B78B45 100%);-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;color:transparent}

